head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60200";
scwin.btn_close_t = 1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60200.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "slc_mainDoc", attr: "__items", fn: function () { return [["", String((dma_pageContext.get("cbMainTop") ?? ""))]]; } },
        { childId: "slc_attachedDoc", attr: "__items", fn: function () { return [["", String((dma_pageContext.get("cbAttchTop") ?? ""))]]; } },
        { childId: "slc_orgDisclsId", attr: "__items", fn: function () { return [["", String((dma_pageContext.get("cbOrgDisclsTop") ?? ""))], ["discls", String((dma_pageContext.get("disclsTitle") ?? ""))]]; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_tempTitle", fn: function () { return "[" + String((dma_pageContext.get("comAbbrv") ?? "")) + "] " + String((dma_pageContext.get("strTitle") ?? "")); } },
        { childId: "__rb0", fn: function () { return String((dma_pageContext.get("comAbbrv") ?? "")) + " " + String((dma_pageContext.get("repIsuSrtCd") ?? "")); } },
        { childId: "__rb1", fn: function () { return "[" + String((dma_pageContext.get("comAbbrv") ?? "")) + "] " + String((dma_pageContext.get("disclsTitle") ?? "")); } },
        { childId: "__rb2", fn: function () { return "본 공지사항은 공시내용 기재 불충분 등의 사유로 한국거래소 " + String((dma_pageContext.get("ldMktTpTxt") ?? "")) + " 정정요구를 받은 사항입니다."; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    let docNo = "";
    if ($("#slc_mainDoc option:selected").val() !== "") {
        const temps = $("#slc_mainDoc option:selected").val().split("|");
        docNo = temps[0];
        const lstYn = temps[1];
        if ("N" === lstYn) {
            /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        } else {
            /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        }
        $("#slc_attachedDoc option:first").attr("selected", "selected");
        if (docNo != null && docNo !== "") {
            search(docNo);
            $("#docdownloadform").find("#docNo").val(docNo);
            $("#docdownloadform").find("#fileName").val("[null] " + $("#slc_mainDoc option:selected").text());
        }
    }
    const title = $("#frm").find("#tempTitle").val();
    fnSetCookieDiscls('null', title);
    if (docNo.length > 1) {
        search(docNo);
        $("#docdownloadform").find("#docNo").val(docNo);
        $("#docdownloadform").find("#fileName").val("[null] " + $("#slc_mainDoc option:selected").text());
    }
    const gubn = 'null';
    const reqTpCd = 'null';
    if (gubn === '1') {
        ($c.util.getComponent("divOrgDiscls") && $c.util.getComponent("divOrgDiscls").show ? $c.util.getComponent("divOrgDiscls").show() : console.warn('[sdd] show 대상 미해결: ' + "divOrgDiscls"));
        $c.util.getComponent("tocTd").setStyle('top', '150px');
        $c.util.getComponent("doc").setStyle('top', '155px');
    } else {
        if (gubn === '2') {
            if (reqTpCd === '01') {
                doLayerPopup('show');
            }
        }
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.dial();
        const userAgent = navigator.userAgent.toLowerCase();
        if (userAgent.match(/ipad|iphone|android/) != null) {
            /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        }
        scwin.fnTocInit();
        scwin.btn_close_t = parseInt($('section.toc-wrapper a.btn-close').css("top"));
        scwin.fnTocResize();
        $(window).resize(function() {
                scwin.fnTocResize();
        });
        scwin.init();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_executeURLLink_onclick
 * @description btn_executeURLLink 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_executeURLLink_onclick = function(e){
    try {
        scwin.executeURLLink()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.btn_executeURLLink_onclick' }); }
};

/**
 * @method
 * @name btn_facebook_onclick
 * @description btn_facebook 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_facebook_onclick = function(e){
    try {
        facebook()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.btn_facebook_onclick' }); }
};

/**
 * @method
 * @name btn_twitter_onclick
 * @description btn_twitter 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
