 */
scwin.btn_twitter_onclick = function(e){
    try {
        twitter()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.btn_twitter_onclick' }); }
};

/**
 * @method
 * @name slc_mainDoc_onchange
 * @description slc_mainDoc 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_mainDoc_onchange = function(e){
    try {
        scwin.fnChangeDoc(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.slc_mainDoc_onchange' }); }
};

/**
 * @method
 * @name slc_attachedDoc_onchange
 * @description slc_attachedDoc 변경 이벤트
