 * @returns {void}
 * @hidden N
 */
scwin.slc_attachedDoc_onchange = function(e){
    try {
        scwin.fnChangeAttachDoc(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.slc_attachedDoc_onchange' }); }
};

/**
 * @method
 * @name btn_pdfPrint_onclick
 * @description btn_pdfPrint 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_pdfPrint_onclick = async function(e){
    try {
        await scwin.pdfPrint();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60200.btn_pdfPrint_onclick' }); }
};

/**
 * @method
 * @name btn_excelDownload_onclick
 * @description btn_excelDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
