 */
scwin.btn_excelDownload_onclick = async function(e){
    try {
        await scwin.excelDownload();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60200.btn_excelDownload_onclick' }); }
};

/**
 * @method
 * @name btn_printDocument_onclick
 * @description btn_printDocument 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_printDocument_onclick = function(e){
    try {
        scwin.printDocument();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.btn_printDocument_onclick' }); }
