/**
 * @method
 * @name slc_orgDisclsId_onchange
 * @description slc_orgDisclsId 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_orgDisclsId_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.openOrgDiscls(selfVar);return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.slc_orgDisclsId_onchange' }); }
};

/**
 * @method
 * @name button_96_onclick
 * @description 「확인」 클릭 이벤트
