 */
scwin.button_96_onclick = function(e){
    try {
        doLayerPopup('hide')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60200.button_96_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fnPdfJson_ajaxsubmit
 * @description fn Pdf Json ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnPdfJson_ajaxsubmit = async function () {
    try { return await $c.data.downFile("/common/pdfDownload.do", "", ($c.util.getComponent("dma_fnPdfJsonAjaxsubmitReq") ? $c.util.getComponent("dma_fnPdfJsonAjaxsubmitReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name executeURLLink
 * @description execute URLLink 처리
 * @returns {void}
 * @hidden N
 */
scwin.executeURLLink = function () {
    const form = $("form[name=frm]");
    const msg = "null - " + $("#ipt_tempTitle", form).val();
    const url = document.location.href;
    const send_link = "kakaolink://sendurl?msg=" + msg + "&url=[" + encodeURIComponent(url) + "]&appid=kind.krx.co.kr&appver=1.0&type=link&appname=[KIND]&apiver=1.0";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(send_link));
};

/**
 * @method
 * @name callDigitalDesc
 * @description call Digital Desc 처리
 * @param {String} pIsurCd pIsurCd
 * @returns {void}
 * @hidden N
 */
scwin.callDigitalDesc = function (pIsurCd) {
    const url = "/digital/digitalCorpList.do?method=digitalCorpList&listApplntIsurCd=" + pIsurCd;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "_blank", scrollbars: true, type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name dial
 * @description dial 처리
 * @returns {void}
 * @hidden N
 */
scwin.dial = function () {
    ($.fn && $.fn.dialog ? $("#dialogLoading").dialog({ title: '자료를 요청 중입니다.', height: 100, closeOnEscape: false, draggable: false, resizable: false, modal: true }) : undefined);
    $("#dialogLoading").attr("title", "자료를 요청 중입니다.");
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $(".ui-widget-overlay").css("background-image", "none");
};

/**
 * @method
 * @name openOrgDiscls
 * @description open Org Discls 처리
 * @param {*} selectObj selectObj
 * @returns {void}
 * @hidden N
 */
scwin.openOrgDiscls = function (selectObj) {
    if (selectObj.options.value === "discls") {
        scwin.openDisclsViewer('null', '');
    }
};

/**
 * @method
 * @name fnMainDocSet
 * @description fn Main Doc Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnMainDocSet = function () {
    const len = $("#slc_mainDoc option").size();
    if (len > 1) {
        $("#slc_mainDoc option:eq(1)").attr("selected", "selected");
    }
};

/**
 * @method
 * @name fnChangeDoc
 * @description fn Change Doc 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnChangeDoc = function () {
    if ($("#slc_mainDoc option:selected").val() !== "") {
        const temps = $("#slc_mainDoc option:selected").val().split("|");
        const docNo = temps[0];
        const lstYn = temps[1];
        if ("N" === lstYn) {
            /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        } else {
            /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        }
        $("#slc_attachedDoc option:first").attr("selected", "selected");
        if (docNo != null && docNo !== "") {
            search(docNo);
            $("#docdownloadform").find("#docNo").val(docNo);
            $("#docdownloadform").find("#fileName").val("[null] " + $("#slc_mainDoc option:selected").text());
        }
    }
};

/**
 * @method
 * @name fnChangeAttachDoc
 * @description fn Change Attach Doc 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnChangeAttachDoc = function () {
    const docNo = $("#slc_attachedDoc option:selected").val();
    $("#slc_mainDoc option:first").attr("selected", "selected");
    if (docNo != null && docNo !== "") {
        search(docNo);
        $("#docdownloadform").find("#docNo").val(docNo);
        $("#docdownloadform").find("#fileName").val($("#frm").find("#tempTitle").val() + " " + $("#slc_attachedDoc option:selected").text());
    }
};

/**
 * @method
 * @name setPath
 * @description set Path 처리
 * @param {*} tocLocPath tocLocPath
 * @param {*} ipt_docLocPath ipt_docLocPath
 * @param {*} docServerPath docServerPath
 * @param {String} ipt_formUpclssCd ipt_formUpclssCd
 * @param {String} ipt_sndLocTpCd ipt_sndLocTpCd
 * @returns {void}
 * @hidden N
 */
scwin.setPath = function (tocLocPath, ipt_docLocPath, docServerPath, ipt_formUpclssCd, ipt_sndLocTpCd) {
    const url = location.href;
    if (url.indexOf("https://") !== -1) {
        tocLocPath = tocLocPath.replace("http://", "https://");
        ipt_docLocPath = ipt_docLocPath.replace("http://", "https://");
    }
    if (url.indexOf("/idev") !== -1) {
        tocLocPath = tocLocPath.replace("/dev", "/idev");
        ipt_docLocPath = ipt_docLocPath.replace("/dev", "/idev");
    }
    let actpno = $("#frm").find("#acptNo").val();
    if (actpno != null) {
        actpno = actpno.substring(0, 8);
    }
    if (tocLocPath === "") {
        $('section.toc-wrapper a.btn-close').click();
        const tocPath = "/common/noToc.htm";
        (($c.util.getComponent('toc')) && ($c.util.getComponent('toc')).setSrc ? ($c.util.getComponent('toc')).setSrc(tocPath) : console.error('[sdd] setSrc 미지원 컴포넌트: toc'));
    } else {
        (($c.util.getComponent('toc')) && ($c.util.getComponent('toc')).setSrc ? ($c.util.getComponent('toc')).setSrc(tocLocPath) : console.error('[sdd] setSrc 미지원 컴포넌트: toc'));
        $("#toc").load(function() {
                $("#toc").contents().find('link').attr('href', '/external/dart_toc.css');
                $("#toc").contents().find("a").attr("target", "docViewFrm");
        });
    }
    document.docViewFrm.location.href = ipt_docLocPath;
    $("#docViewFrm").load(function() {
            if ($("#docViewFrm").contents().find('link').length > 0) {
                if ($("#docViewFrm").contents().find('link').attr('href').indexOf('/external/report_xml.css') !== -1) {
                    $("#docViewFrm").contents().find('link').attr('href', '/external/report_xml.css');
                } else {
                    if ($("#docViewFrm").contents().find('link').attr('href').indexOf('/external/xforms.css') !== -1) {
                        $("#docViewFrm").contents().find('link').attr('href', '/external/xforms.css');
                    }
                }
            }
    });
    $("#docdownloadform").find("#docLocPath").val(ipt_docLocPath);
    $("#docdownloadform").find("#docpath").val(docServerPath);
    $("#frm").find("#sndLocTpCd").val(ipt_sndLocTpCd);
    $("#frm").find("#formUpclssCd").val(ipt_formUpclssCd);
};

/**
 * @method
 * @name setPath2
 * @description set Path2 처리
 * @param {*} tocLocPath tocLocPath
 * @param {*} ipt_docLocPath ipt_docLocPath
 * @param {*} docServerPath docServerPath
 * @param {String} ipt_formUpclssCd ipt_formUpclssCd
 * @param {String} ipt_sndLocTpCd ipt_sndLocTpCd
 * @returns {void}
 * @hidden N
 */
scwin.setPath2 = function (tocLocPath, ipt_docLocPath, docServerPath, ipt_formUpclssCd, ipt_sndLocTpCd) {
    if (tocLocPath === "") {
        $('section.toc-wrapper a.btn-close').click();
        document.toc.location.href = "/common/noToc.htm";
        document.docViewFrm.location.href = "/common/JLDDST60200_i2.jsp?docpath=" + ipt_docLocPath;
    } else {
        document.toc.location.href = tocLocPath;
        document.docViewFrm.location.href = "/common/JLDDST60200_i2.jsp?docpath=" + ipt_docLocPath;
    }
    $c.util.getComponent('dma_fnPdfJsonAjaxsubmitReq').set('docLocPath', ipt_docLocPath);
    $c.util.getComponent('dma_fnPdfJsonAjaxsubmitReq').set('docpath', docServerPath);
    $c.util.getComponent('dma_fnPdfJsonAjaxsubmitReq').set('sndLocTpCd', ipt_sndLocTpCd);
    $c.util.getComponent('dma_fnPdfJsonAjaxsubmitReq').set('formUpclssCd', ipt_formUpclssCd);
};

/**
 * @method
 * @name pdfPrint
 * @description pdf Print 처리
 * @param {*} button button
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pdfPrint = async function (button) {
    let isEsgDiscls = true;
    const maindocFileNm = $c.util.getComponent('dma_fnPdfJsonAjaxsubmitReq').get('docLocPath');
    if (isEsgDiscls) {
        let flag = true;
        $("#docViewFrm").contents().find(".TABLE").each(function() {
                if (this.width > 1350) {
                    isEsgDiscls = false;
                }
        });
        if (!isEsgDiscls) {
            await scwin.fnPdfJson();
            return;
        }
        if (!button) {
            flag = await $c.win.confirm("PDF파일 저장은 인쇄팝업에서 PDF로 저장항목을 선택하고 하단의 저장 버튼을 클릭하세요.");
        }
        const iframeWin = frames["docViewFrm"];
        const idoc = iframeWin.document;
        if (flag) {
            $("#docViewFrm").contents().find("table.fact-table").each(function() {
                    if ($(this).attr('style') === 'width:1550px;') {
                        $(this).removeAttr('style');
                    }
                    const docView = frames["docViewFrm"];
                    const printStyle = docView.document.createElement("style");
                    printStyle.textContent = `
                                @page{
                                        size: portrait;

                                }
                                body{
                                        zoom: 0.80;
                                		box-sizing:border-box;
                                		margin-right: 20px;

                                }
                                table{
                                    	width: 100%;
                                    	table-layout: fixed;
                                    	word-wrap: break-word;
                            	}

                        `;
                    docView.document.head.appendChild(printStyle);
            });
            $("#docViewFrm").contents().find("div.preview_wrap").width(1040);
            if (maindocFileNm.indexOf("80752.htm") > -1) {
                let docView = frames["docViewFrm"];
                let printStyle = docView.document.createElement("style");
                printStyle.textContent = `
						@page{
							size: landscape;
							margin: 0;
						}
						body{
							zoom: 0.90;
						}
					`;
                docView.document.head.appendChild(printStyle);
            } else {
                docView = frames["docViewFrm"];
                printStyle = docView.document.createElement("style");
                printStyle.textContent = `
                            @page{
                                    size: portrait;

                            }
                            body{
                                    zoom: 0.80;
                            		box-sizing:border-box;
                            		margin-right: 20px;

                            }
                            table{
                                	width: 100%;
                                	table-layout: fixed;
                                	word-wrap: break-word;
                        	}

                    `;
                docView.document.head.appendChild(printStyle);
            }
            $("#docViewFrm").contents().find(".nb").each(function() {
                    if (this.width > 1250) {
                        $(this).removeAttr('width');
                        this.style.maxWidth = "1250px";
                        this.style.minWidth = "1250px";
                        this.style.width = "1250px";
                        this.style.tableLayout = "auto";
                    }
            });
            $("#docViewFrm").contents().find(".TABLE").each(function() {
                    if (this.width > 1250) {
                        $(this).removeAttr('width');
                        this.style.maxWidth = "1250px";
                        this.style.minWidth = "1250px";
                        this.style.width = "1250px";
                        this.style.tableLayout = "auto";
                        $(this).find('colgroup col').each(function() {
                                $(this).removeAttr('width');
                        });
                    }
            });
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            frames["docViewFrm"].print();
        } else {
            return;
        }
    } else {
        await scwin.fnPdfJson();
    }
};

/**
 * @method
 * @name fnPdfJson
 * @description fn Pdf Json 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnPdfJson = async function () {
    $("#docdownloadform").find("#method").val("pdfDownJson");
    await scwin.tx_fnPdfJson_ajaxsubmit();
};

/**
 * @method
 * @name fnPdfJsonCallBack
 * @description fn Pdf Json Call Back 처리
 * @param {*} response response
 * @param {*} status status
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnPdfJsonCallBack = async function (response, status) {
    if (status === "success") {
        const items = response;
        if (items.length === 1) {
            const filestatus = items[0].filestatus;
            if (filestatus === "empty") {
                let message = "PDF가 아직 변환되지 않았습니다. 처리중이오니 잠시후 다시 클릭하시기 바랍니다.";
                await $c.win.alert(message);
                return;
            } else {
                message = "PDF 파일 변환 중 오류가 발생하였습니다. 잠시 후 다시 시도해 주시기 바랍니다.";
                await $c.win.alert(message);
                return;
            }
        } else {
            filedownload('pdf');
        }
    }
};

/**
 * @method
 * @name excelDownload
 * @description excel Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDownload = async function () {
    let isEsgDiscls = false;
    const maindocFileNm = $c.util.getComponent('dma_fnPdfJsonAjaxsubmitReq').get('docLocPath');
    if (maindocFileNm.indexOf("99667.htm") > -1) {
        isEsgDiscls = true;
    }
    if (maindocFileNm.indexOf("99926.htm") > -1) {
        isEsgDiscls = true;
    }
    if (isEsgDiscls) {
        await $c.win.alert('해당서식은 Excel 다운로드 기능을 제공하지 않습니다.');
    } else {
        filedownload('excel');
    }
};

/**
 * @method
 * @name fnTocInit
 * @description fn Toc Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnTocInit = function () {
    $('#toc').attr("allowTransparency", "true");
    $('section.toc-wrapper a.btn-close').bind('click', function() {
            $('section.toc-wrapper').addClass("hide");
            $('div.layer-opener-wrapper').addClass("active");
            (($c.util.getComponent('doc')) && ($c.util.getComponent('doc')).addClass ? ($c.util.getComponent('doc')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: doc'));
            setTimeout(function(){ scwin.fnTocResize() }, 100);
    });
    $('div.layer-opener-wrapper a.btn-open').bind('click', function() {
            $('section.toc-wrapper').removeClass("hide");
            $('div.layer-opener-wrapper').removeClass("active");
            (($c.util.getComponent('doc')) && ($c.util.getComponent('doc')).removeClass ? ($c.util.getComponent('doc')).removeClass("active") : console.error('[sdd] removeClass 미지원 컴포넌트: doc'));
            setTimeout(function(){ scwin.fnTocResize() }, 100);
    });
};

/**
 * @method
 * @name fnTocResize
 * @description fn Toc Resize 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnTocResize = function () {
    const x = $("section.contents").offset();
    const tocTdWidth = $(".openToc").width() + 30;
    const bh = $("body").height();
    const bw = $("body").width();
    const h = bh - 265;
    $("#toc").height(h);
    $("#docViewFrm").height(h + 28);
    $("#docViewFrm").width(bw - tocTdWidth);
    $('div.layer-opener-wrapper a.btn-open').height(h - 61);
};

